import glob,re,os
from collections import Counter
def parse(p):
    d={}
    for line in open(p):
        m=re.match(r'^(\w+):\s*(.*)$',line)
        if m: d[m.group(1)]=m.group(2).strip()
    return d
rows=[]
for p in sorted(glob.glob('*.yaml')):
    d=parse(p); d['_p']=p; rows.append(d)
op=[r for r in rows if r.get('status')=='open']
print('total',len(rows),'open',len(op))
print(Counter(r.get('kind') for r in op))
print(Counter(r.get('owner') for r in op))
for r in op:
    print(r['_p'], r.get('kind'), 'owner=',r.get('owner'),'aud=',r.get('audience'),'labels_next')
